        var src = file_read({ path: 'js/pushReworkChanges.js' });
        assert.ok(/require\('\.\/common\/toolchainSummary\.js'\)/.test(src),
            'rework leg must require ./common/toolchainSummary.js');
        assert.ok(/withToolchainLine/.test(src),
