            file_read: function(opts) {
                seen.push(opts.path);
                return opts.path === 'repo/setup/dart.sh' ? '#!/usr/bin/env bash' : null;
            },
            cli_execute_command: function(args) {
                argsUsed = args;
                return 'toolchain: dart 3.13.5 (CI: 3.13.5, match: yes)';
            }
        });
